// Simple endless runner based on IDEA.md
(function(){
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const w = canvas.width = canvas.offsetWidth || 800;
  const h = canvas.height = canvas.offsetHeight || 200;
  // Player
  const player = {x:50, y:h-30, w:20, h:20, vy:0, jumpStrength:-8};
  const gravity = 0.4;
  // Obstacles
  const obstacles = [];
  let spawnTimer = 0;
  const spawnInterval = 90; // frames
  let speed = 3;
  let running = true;
  function reset(){
    player.y = h-30; player.vy=0; obstacles.length=0; spawnTimer=0; speed=3; running=true;
  }
  function gameOver(){
    running=false;
    ctx.fillStyle='rgba(0,0,0,0.5)';
    ctx.fillRect(0,0,w,h);
    ctx.fillStyle='white';
    ctx.font='24px sans-serif';
    ctx.fillText('Game Over - Press Space to Restart', w/2-180, h/2);
  }
  function spawnObstacle(){
    const type = Math.random()<0.5?'bar':'spike';
    const o = {x:w, w:20, type};
    if(type==='bar'){
      o.h = 30; o.y = h - o.h;
    } else {
      o.h = 20; o.y = h - o.h;
    }
    obstacles.push(o);
  }
  function update(){
    if(!running) return;
    // player physics
    player.vy += gravity;
    player.y += player.vy;
    if(player.y > h - player.h){player.y = h - player.h; player.vy=0;}
    // obstacles
    spawnTimer++;
    if(spawnTimer > spawnInterval){spawnObstacle(); spawnTimer=0;}
    for(let i=obstacles.length-1;i>=0;i--){
      const o = obstacles[i];
      o.x -= speed;
      // collision
      if(o.x < player.x+player.w && o.x+o.w > player.x &&
         o.y < player.y+player.h && o.y+o.h > player.y){
        gameOver();
        return;
      }
      if(o.x+o.w < 0) obstacles.splice(i,1);
    }
    // increase speed gradually
    speed += 0.001;
  }
  function draw(){
    ctx.clearRect(0,0,w,h);
    // player
    ctx.fillStyle='lime';
    ctx.fillRect(player.x,player.y,player.w,player.h);
    // obstacles
    ctx.fillStyle='red';
    obstacles.forEach(o=>{
      ctx.fillRect(o.x,o.y,o.w,o.h);
    });
  }
  function loop(){
    update();
    draw();
    requestAnimationFrame(loop);
  }
  // input
  window.addEventListener('keydown',e=>{
    if(e.code==='Space'){
      if(!running) reset();
      if(player.vy===0) player.vy=player.jumpStrength;
    }
  });
  canvas.addEventListener('click',()=>{if(player.vy===0) player.vy=player.jumpStrength;});
  loop();
})();
